if ($json.errors?.length) {
  throw new Error("Neo4j fejl: " + JSON.stringify($json.errors));
}
const result = $json.results?.[0];
const columns = result?.columns ?? [];
const rows = (result?.data ?? []).map(item =>
  Object.fromEntries(columns.map((c, i) => [c, item.row[i]]))
);
const meta = $('Build query').first().json.meta;

return [{ json: {
  source: meta.source,
  ...meta.info,
  count: rows.length,
  results: rows,
  note: rows.length === 0
    ? "Ingen resultater i databasen. Fortæl brugeren det ærligt og foreslå en anden søgning."
    : "Brug kun disse resultater. Angiv track_id/kilde, når du citerer dem."
}}];
